			text = [=[Talonaxe se lembrou do voo na hora. Tinha enviado seu melhor cavaleiro para voar com {link:brohann-caskbelly}Brohann{/link} sobre o pântano em busca de um templo afogado. O cavaleiro era {link:rhapsody-shindigger}Rhapsody Shindigger{/link}, e ninguém no aviário voava como ele. Mas Rhapsody voltou desse voo abalado e sedento, e sua sede só cresceu. No fim, o mestre do aviário teve de mandá-lo embora.]=],
		},
		{
			title = "O Herdeiro Perdido",
			hint = [=[Procure um jovem grifo desaparecido nas aldeias trolls e no Altar de Zul.]=],
			text = [=[Sharpbeak, o herdeiro do grifo mais poderoso do aviário, desapareceu enquanto caçava com os pais. Talonaxe tinha certeza de que trolls o haviam levado. As jaulas das aldeias {link:witherbark-trolls}Cascasseca{/link} foram vasculhadas e encontradas vazias. O {link:the-altar-of-zul}Altar de Zul{/link}, onde os Ramatorpe fazem seus sacrifícios, foi vasculhado em seguida. O jovem grifo também não estava lá, e Talonaxe não sabia se devia chorar ou se alegrar.]=],
		},
		{
			title = "Uma Pena e um Adivinho",
			hint = [=[Leve uma pena do ninho de Sharpbeak ao adivinho de Etergarde.]=],
			text = [=[Com todas as trilhas esfriadas, Talonaxe recorreu a {link:thadius-grimshade}Thadius Grimshade{/link}. Grimshade deixara o {link:aerie-peak}Ninho da Águia{/link} anos antes em busca de saberes mais sombrios, mas Talonaxe ainda o chamava de Martelo Feroz de coração. Uma pena do ninho onde o jovem grifo dormia foi enviada à torre do adivinho, para que ele seguisse seu fio de volta até o dono.]=],
		},
		{
			title = "A Jaula no Penhasco",
			hint = "Traga para casa o jovem grifo mantido pelos Ramatorpe.",
			text = [=[A adivinhação de {link:thadius-grimshade}Grimshade{/link} encontrou Sharpbeak numa jaula no alto de um penhasco em {link:jintha-alor}Jintha'Alor{/link}. A chave pendia do cinto da {link:vile-priestess-hexx}Sacerdotisa Vil Hexx{/link}. Os Martelo Feroz não suportaram aquilo. A sacerdotisa tombou, a jaula foi aberta, e Sharpbeak voou para casa, para os pais. Talonaxe os viu mimar o filho, e os olhos do velho {link:dwarves}anão{/link} não estavam secos.]=],
		},
	},
	mentions = {
		{ text = "Mestre dos Grifos Talonaxe" },
		{ text = "{link:rhapsody-shindigger}Rhapsody Shindigger{/link}" },
		{ text = "Jaulas {link:witherbark-trolls}Cascasseca{/link}" },
		{ text = "O {link:the-altar-of-zul}Altar de Zul{/link}" },
		{ text = "{link:thadius-grimshade}Thadius Grimshade{/link}" },
		{ text = "De Volta às {link:the-hinterlands}Terras Agrestes{/link}" },
		{ text = "Salvando Sharpbeak" },
	},
	bonds = {
