	hint = "Fale com a troll que comanda a Aldeia Revatusco.",
	allegiance = "Trolls Revatusco · Horda",
	aliases = { "Torntusk" },
	sections = {
		{
			title = "Resumo",
			text = [=[Primal Torntusk comanda a {link:revantusk-village}Aldeia Revatusco{/link}. Suas ordens saem em seu próprio nome, e suas recompensas ficam afixadas para todos verem. É uma guerreira dos {red:revantusk-trolls}Revatusco{/red} e uma sábia de seu povo, e conhece as artes sombrias dos Ramatorpe bem o bastante para desfazê-las. Quando os Ramatorpe vieram à noite e levaram seu companheiro, ela não se desesperou. Pediu ajuda e foi à guerra.]=],
		},
		{
			title = "Importância",
			text = [=[Torntusk mantém o ponto de apoio da {link:horde}Horda{/link} nas {link:the-hinterlands}Terras Agrestes{/link}. Sua aldeia é pequena e cercada de inimigos: os Ramatorpe ao norte e a oeste, as feras selvagens das colinas e os Martelo Feroz do outro lado da região. Sob ela, os {link:revantusk-village}Revatusco{/link} tornaram-se o inimigo mais obstinado dos Ramatorpe. Só ela, entre eles, parece entender que o verdadeiro inimigo não é a tribo, mas o deus a que ela serve.]=],
		},
		{
			title = "Feitos",
			text = [=[• Reergueu sua aldeia depois que um ataque Ramatorpe levou seu companheiro e seu capitão da guarda.
• Purificou os vasos de sangue maculado trazidos de {link:jintha-alor}Jintha'Alor{/link}.
• Pôs um preço pela cabeça da {link:vile-priestess-hexx}Sacerdotisa Vil Hexx{/link} e de sua guarda Aman'zasi.
• Busca um novo capitão da guarda para substituir o falecido Malkhor.]=],
		},
	},
	chapters = {
		{
			title = "O Ataque da Meia-noite",
			hint = "Resgate o companheiro da líder Revatusco em Jintha'Alor.",
			text = [=[Os Ramatorpe vieram no meio da noite e levaram o {link:elder-torntusk}Ancião Torntusk{/link} vivo. Os espiões {link:revantusk-village}Revatusco{/link} descobriram que ele era mantido no topo de {link:jintha-alor}Jintha'Alor{/link} e que {link:vile-priestess-hexx}Hexx{/link} pretendia oferecê-lo a {link:hakkar}Hakkar{/link}. Torntusk disse com clareza que sua aldeia não suportaria tal perda. Os grilhões foram quebrados, o ancião voltou para casa, e a dívida dos Revatusco foi grande.]=],
		},
		{
			title = "Afrouxando as Garras",
			hint = [=[Roube os vasos maculados de Jintha'Alor para Primal Torntusk.]=],
			text = [=[Torntusk entendeu que os Ramatorpe não lutavam com a própria força. O sangue em seus vasos carregava o poder do deus sem rosto, e os enlouquecia. Quando os vasos lhe foram trazidos, ela extraiu deles a mácula. As garras do {link:hakkar}deus do sangue{/link} se afrouxaram. Ela advertiu seu povo de que era apenas por um tempo.]=],
		},
		{
			title = "Um Capitão para Revatusco",
			hint = "Prove ser digno do posto de capitão da guarda Revatusco.",
			text = [=[Com Malkhor morto, o posto de capitão da guarda ficou vago. Torntusk fez um chamado a quem quer que reduzisse as fileiras dos guerreiros, caçadores das sombras, bebedores de sangue e devoradores de almas Ramatorpe. Os que responderam foram agradecidos e recompensados. A escolha em si, disse ela, esperaria até o ano seguinte.]=],
		},
	},
	mentions = {
		{
			text = [=[O {link:elder-torntusk}Ancião Torntusk{/link} Foi Sequestrado!]=],
		},
		{ text = "De Volta a Primal Torntusk" },
		{ text = "Vasos Sombrios" },
		{
			text = [=[Procura-se: {link:vile-priestess-hexx}Sacerdotisa Vil Hexx{/link} e Seus Lacaios]=],
		},
		{
			text = [=[Vaga Aberta: Capitão da Guarda da {link:revantusk-village}Aldeia Revatusco{/link}]=],
		},
	},
	bonds = {
		{ id = "elder-torntusk", name = "Ancião Torntusk", note = "seu companheiro" },
		{ id = "huntsman-markhor", name = "Caçador Markhor", note = "irmão de seu capitão tombado" },
		{ id = "vile-priestess-hexx", name = "Sacerdotisa Vil Hexx", note = "sua inimiga" },
		{ id = "falstad-wildhammer", name = "Falstad Wildhammer", note = "thane dos anões que seu povo odeia" },
	},
})

